public class METCredManTmpStatusCheckSetupEventHandler
{
    private FormDataSource formDataSource;

}

Method.Source:
internal static void subscribe(FormDataSource _formDataSource)
{
    METCredManTmpStatusCheckSetupEventHandler handler = METCredManTmpStatusCheckSetupEventHandler::construct(_formDataSource);
    handler.addEvents();
}

private static METCredManTmpStatusCheckSetupEventHandler construct(FormDataSource _formDataSource)
{
    METCredManTmpStatusCheckSetupEventHandler handler = new METCredManTmpStatusCheckSetupEventHandler();
    handler.formDataSource = _formDataSource;

    return handler;
}

private void addEvents()
{
    formDataSource.OnActivated += eventhandler(this.OnActivated);

    formDataSource.object(fieldNum(CredManTmpStatusCheckSetup, CheckPosting)).OnModified += eventhandler(this.fieldModified_CheckPosting);
    formDataSource.object(fieldNum(CredManTmpStatusCheckSetup, CheckPostingGraceDays)).OnModified += eventhandler(this.fieldModified_CheckPostingGraceDays);
    formDataSource.object(fieldNum(CredManTmpStatusCheckSetup, CheckProforma)).OnModified += eventhandler(this.fieldModified_CheckProforma);
    formDataSource.object(fieldNum(CredManTmpStatusCheckSetup, CheckProformaGraceDays)).OnModified += eventhandler(this.fieldModified_CheckProformaGraceDays);
}

private void onActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    CredManTmpStatusCheckSetup tmpStatusCheckSetup = sender.cursor();
    this.manageButtons(tmpStatusCheckSetup, sender);
}

private void fieldModified_CheckPosting(FormDataObject sender, FormDataFieldEventArgs e)
{
    CredManTmpStatusCheckSetup tmpStatusCheckSetup = sender.datasource().cursor();
    this.fieldModified(tmpStatusCheckSetup, fieldNum(CredManTmpStatusCheckSetup, CheckPosting));
    this.manageButtons(tmpStatusCheckSetup, sender.datasource());
}

private void fieldModified_CheckPostingGraceDays(FormDataObject sender, FormDataFieldEventArgs e)
{
    CredManTmpStatusCheckSetup tmpStatusCheckSetup = sender.datasource().cursor();
    this.fieldModified(tmpStatusCheckSetup, fieldNum(CredManTmpStatusCheckSetup, CheckPostingGraceDays));
    this.manageButtons(tmpStatusCheckSetup, sender.datasource());
}

private void fieldModified_CheckProforma(FormDataObject sender, FormDataFieldEventArgs e)
{
    CredManTmpStatusCheckSetup tmpStatusCheckSetup = sender.datasource().cursor();
    this.fieldModified(tmpStatusCheckSetup, fieldNum(CredManTmpStatusCheckSetup, CheckProforma));
    this.manageButtons(tmpStatusCheckSetup, sender.datasource());
}

private void fieldModified_CheckProformaGraceDays(FormDataObject sender, FormDataFieldEventArgs e)
{
    CredManTmpStatusCheckSetup tmpStatusCheckSetup = sender.datasource().cursor();
    this.fieldModified(tmpStatusCheckSetup, fieldNum(CredManTmpStatusCheckSetup, CheckProformaGraceDays));
    this.manageButtons(tmpStatusCheckSetup, sender.datasource());
}

private boolean hasGraceDays(CredManDocumentTypeGraceDays _postingGraceDays, CredManDocumentTypeGraceDays _proformaGraceDays, NoYes _isProformaRelated)
{
    return _isProformaRelated == NoYes::No ?
            (_postingGraceDays > 0 ? true : false) :
            (_proformaGraceDays > 0 ? true : false);
}

private boolean hasNoGraceDays(CredManDocumentTypeGraceDays _postingGraceDays, CredManDocumentTypeGraceDays _proformaGraceDays, NoYes _isProformaRelated)
{
    return _isProformaRelated == NoYes::No ?
            (_postingGraceDays == 0 ? true : false) :
            (_proformaGraceDays == 0 ? true : false);
}

private boolean hasValidGraceDaysForAllDocuments(
    CredManStatusCheckSetup _credManStatusCheckSetup,
    CredManTmpStatusCheckSetup _tmpStatusCheckSetup,
    NoYes _isProformaRelated)
{
    boolean ret = true;
    ret = !(this.hasGraceDays(_tmpStatusCheckSetup.CheckPostingGraceDays,
                              _tmpStatusCheckSetup.CheckProformaGraceDays,
                              _isProformaRelated)
          && CredManStatusCheckSetup::METhasAnyDocumentWithZeroGraceDays(CredManHoldType::Credit, _credManStatusCheckSetup.RecId));
    if (!ret)
    {
        info("@CreditManagement:CredManStatusCheckSetupSetGraceDaysMin");
    }
    return ret;
}

private boolean hasValidNoGraceDaysForAllDocuments(
    CredManStatusCheckSetup _credManStatusCheckSetup,
    CredManTmpStatusCheckSetup _tmpStatusCheckSetup,
    NoYes _isProformaRelated)
{
    boolean ret = true;
    ret = !(this.hasNoGraceDays(_tmpStatusCheckSetup.CheckPostingGraceDays,
                                _tmpStatusCheckSetup.CheckProformaGraceDays,
                                _isProformaRelated)
          && CredManStatusCheckSetup::METhasAnyDocumentWithZeroGraceDays(CredManHoldType::Credit, _credManStatusCheckSetup.RecId)
          && Box::yesNo("@CreditManagement:CredManStatusCheckSetupResetGraceDaysConfirm",
                         DialogButton::Yes,
                         "@CreditManagement:Confirmation") == dialogButton::Yes);
    return ret;
}

private void setMinimumGraceDays(CredManTmpStatusCheckSetup _tmpStatusCheckSetup, NoYes _isProformaRelated)
{
    if (_isProformaRelated == NoYes::No)
    {
        _tmpStatusCheckSetup.CheckPostingGraceDays = 1;
    }
    else
    {
        _tmpStatusCheckSetup.CheckProformaGraceDays = 1;
    }
}

private void adjustGraceDaysForAllDocuments(CredManTmpStatusCheckSetup _tmpStatusCheckSetup, NoYes _isProformaRelated)
{
    CredManStatusCheckSetup statusCheckSetup = CredManStatusCheckSetup::METfind(CredManHoldType::Credit,
                                                                             _tmpStatusCheckSetup.DocumentStatus,
                                                                             _isProformaRelated,
                                                                             true);
    if (!statusCheckSetup)
    {
        return;
    }

    boolean inValidGraceDaysAndSetMinimumValue = !this.hasValidGraceDaysForAllDocuments(statusCheckSetup,
                                                                                        _tmpStatusCheckSetup,
                                                                                        _isProformaRelated);
    boolean inValidGraceDaysAndSetZeroValue = !this.hasValidNoGraceDaysForAllDocuments(statusCheckSetup,
                                                                                       _tmpStatusCheckSetup,
                                                                                       _isProformaRelated);
    boolean updateTmpStatusCheckGraceDays = (inValidGraceDaysAndSetMinimumValue || inValidGraceDaysAndSetZeroValue);

    ttsbegin;
    if (this.hasGraceDays(_tmpStatusCheckSetup.CheckPostingGraceDays, _tmpStatusCheckSetup.CheckProformaGraceDays, _isProformaRelated))
    {
        statusCheckSetup.GraceDays = _isProformaRelated == NoYes::No ?
                                        _tmpStatusCheckSetup.CheckPostingGraceDays :
                                        _tmpStatusCheckSetup.CheckProformaGraceDays;
    }
    else
    {
        if (CredManStatusCheckSetup::METhasAnyDocumentWithZeroGraceDays(CredManHoldType::Credit, statusCheckSetup.RecId))
        {
            this.setMinimumGraceDays(_tmpStatusCheckSetup, _isProformaRelated);
            statusCheckSetup.GraceDays = 1;
        }
        else
        {
            statusCheckSetup.GraceDays = 0;
        }
    }

    if (statusCheckSetup.validateWrite())
    {
        statusCheckSetup.update();
    }

    if (inValidGraceDaysAndSetMinimumValue)
    {
        CredManStatusCheckSetup::METsetDocumentsWithZeroGraceDaysToOne(CredManHoldType::Credit);
    }
    else if (inValidGraceDaysAndSetZeroValue)
    {
        CredManStatusCheckSetup::METsetAllDocumentsGraceDaysToZero(CredManHoldType::Credit);
    }

    if (updateTmpStatusCheckGraceDays)
    {
        CredManTmpStatusCheckSetup::METupdateGraceDays(_tmpStatusCheckSetup, CredManHoldType::Credit);
    }
    ttscommit;

    formDataSource.research(true);
}

private void updateCheckPosting(CredManTmpStatusCheckSetup _tmpStatusCheckSetup)
{
    if (_tmpStatusCheckSetup.CheckPosting == NoYes::Yes)
    {
        CredManStatusCheckSetup::METenableStatusCheck(CredManHoldType::Credit, _tmpStatusCheckSetup.DocumentStatus, NoYes::No);
    }
    else
    {
        if (!CredManStatusCheckSetup::METdisableStatusCheck(CredManHoldType::Credit,
                                                         _tmpStatusCheckSetup.DocumentStatus,
                                                         NoYes::No))
        {
            _tmpStatusCheckSetup.CheckPosting = !_tmpStatusCheckSetup.CheckPosting;
        }
    }

    _tmpStatusCheckSetup.CheckPostingGraceDays = CredManStatusCheckSetup::METfind(CredManHoldType::Credit, _tmpStatusCheckSetup.DocumentStatus, NoYes::No).GraceDays;
}

private void updateCheckProforma(CredManTmpStatusCheckSetup _tmpStatusCheckSetup)
{
    if (_tmpStatusCheckSetup.CheckProforma == NoYes::Yes)
    {
        CredManStatusCheckSetup::METenableStatusCheck(CredManHoldType::Credit, _tmpStatusCheckSetup.DocumentStatus, NoYes::Yes);
    }
    else
    {
        if (!CredManStatusCheckSetup::METdisableStatusCheck(CredManHoldType::Credit,
                                                         _tmpStatusCheckSetup.DocumentStatus,
                                                         NoYes::Yes))
        {
            _tmpStatusCheckSetup.CheckProforma = !_tmpStatusCheckSetup.CheckProforma;
        }
    }

    _tmpStatusCheckSetup.CheckProformaGraceDays = CredManStatusCheckSetup::METfind(CredManHoldType::Credit, _tmpStatusCheckSetup.DocumentStatus, NoYes::Yes).GraceDays;
}

internal void fieldModified(CredManTmpStatusCheckSetup _tmpStatusCheckSetup, int _modifiedFieldId)
{
    switch(_modifiedFieldId)
    {
        case fieldNum(CredManTmpStatusCheckSetup, CheckPosting) :
            this.updateCheckPosting(_tmpStatusCheckSetup);
            break;

        case fieldNum(CredManTmpStatusCheckSetup, CheckPostingGraceDays) :
            this.adjustGraceDaysForAllDocuments(_tmpStatusCheckSetup, NoYes::No);
            break;

        case fieldNum(CredManTmpStatusCheckSetup, CheckProforma) :
            this.updateCheckProforma(_tmpStatusCheckSetup);
            break;

        case fieldNum(CredManTmpStatusCheckSetup, CheckProformaGraceDays) :
            this.adjustGraceDaysForAllDocuments(_tmpStatusCheckSetup, NoYes::Yes);
            break;
    }
}
